PRESERVE={
    'generate_centenas_3plus1','centena_31_freeze_state','decision_contextual_evidence',
    'method_reset_coverage_v1','method_convergencia_g5','historical_pulls',
    'program_update_check','account_sync_now','start_update_search'
}
def method_ast(src, names):
    tree=ast.parse(src); out={}
    for n in ast.walk(tree):
        if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name in names:
            out[n.name]=ast.dump(n,include_attributes=False)
    missing=names-set(out)
    if missing: raise SystemExit(f'Funções preservadas ausentes: {sorted(missing)}')
    return out
before=method_ast(text,PRESERVE)

